// Make the layer `dwg app page` generates (src/finance/dwg) speak English and read the English finance model.
//
// The template is English only. `dwg app page` (Michael Tenner's dwg cli) writes German UI strings, mounts the
// visuals with locale de-DE, and the two page specs were generated from the earlier German model
// (tables dim-konten / fact-guv, measures "GuV AC" ...). This script patches the generated files in place:
// UI strings, the visual locale, slicer value formatting, the page specs' bindings, titles and tree state, and
// the reference DAX next to them. Generator comments and test names stay as the generator wrote them.
//
// Run it after every `dwg app page`; it is idempotent and fails when an expected string is gone (the generator
// changed: look again). The patched output is committed, so a normal build never runs it.
//
//   node tools/finance/dwg-english.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const DWG = resolve(dirname(fileURLToPath(import.meta.url)), '../../src/finance/dwg');

// Model renames (fabric/caldova-cologne-finance.SemanticModel); every occurrence.
const MODEL = [
  ["'dim-konten'", "'dim-account'"],
  ["'fact-guv'", "'fact-pnl'"],
  ['[Kommentar]', '[Comment]'],
  ['[GuV AC]', '[P&L AC]'],
  ['[GuV PY]', '[P&L PY]'],
  ['[GuV PL]', '[P&L PL]'],
  ['[GuV FC]', '[P&L FC]'],
  ['[GuV FC FY]', '[P&L FC FY]'],
  ['[GuV PL FY]', '[P&L PL FY]'],
];

// Account tree names used in the tree view's saved state (tools/data/generate_finance.py).
const TREE = [
  ['L:Wareneinsatz', 'L:Cost of goods sold'],
  ['L:Sonstiges betriebliches Ergebnis', 'L:Other operating result'],
  ['L:Abschreibungen', 'L:Depreciation'],
  ['L:Finanzergebnis', 'L:Financial result'],
  ['L:Steuern vom Einkommen und vom Ertrag', 'L:Income taxes'],
  ['L:Betriebliche Aufwendungen¦Raumkosten', 'L:Operating expenses¦Premises'],
  ['L:Betriebliche Aufwendungen¦Sonstige Aufwendungen', 'L:Operating expenses¦Other expenses'],
];

const SPEC_HEADER = [
  ['"unitLine": "Caldova Logistikzentrum Köln"', '"unitLine": "Caldova logistics centre Cologne"'],
];
// The generator's German header line names the app spec (tools/finance/guv-spec.json); any spec name.
const HEADER = [/^\/\/ erzeugt von `dwg app page` aus der App-Spec „(.+)“, nicht von Hand ändern\.$/m, '// Generated by `dwg app page` from the app spec "$1"; patched by tools/finance/dwg-english.mjs.'];

